var e={key:`get-started/what-is-qym`,sectionId:`get-started`,pageId:`what-is-qym`,articleTitle:`What is qym`,sourcePath:`packages/platform/qym_platform/_static/dashboard/docs/get-started/what-is-qym.html`,sourceBytes:2661,sourceSha256:`bf8963c632fefb9ce475a6f8b78e13f1cfd45d096aa646e524ad5bae00fd2bd1`,headings:[{id:`the-problem-it-solves`,level:2,text:`The problem it solves`},{id:`how-it-works`,level:2,text:`How it works`},{id:`sdk-vs-platform`,level:2,text:`SDK vs. platform`}],blocks:[{type:`paragraph`,variant:`eyebrow`,children:[{type:`text`,value:`Get started`}]},{type:`heading`,level:1,text:`What is qym`,children:[{type:`text`,value:`What is qym`}]},{type:`paragraph`,variant:`lead`,children:[{type:`text`,value:`qym is an evaluation operating system for LLM products. You define a `},{type:`strong`,children:[{type:`text`,value:`task`}]},{type:`text`,value:`, point it at a `},{type:`strong`,children:[{type:`text`,value:`dataset`}]},{type:`text`,value:`, apply one or more `},{type:`strong`,children:[{type:`text`,value:`metrics`}]},{type:`text`,value:`, run it, and inspect the evidence — locally or streamed to this platform.`}]},{type:`heading`,level:2,text:`The problem it solves`,children:[{type:`text`,value:`The problem it solves`}],id:`the-problem-it-solves`},{type:`paragraph`,variant:`body`,children:[{type:`text`,value:`Most teams evaluate LLMs with a scatter of one-off scripts, notebooks, and spreadsheets. Results live on someone's laptop, scoring logic drifts between runs, and nobody can answer "is the new prompt actually better?" with confidence.`}]},{type:`paragraph`,variant:`body`,children:[{type:`text`,value:`qym makes evaluation `},{type:`strong`,children:[{type:`text`,value:`repeatable`}]},{type:`text`,value:` and `},{type:`strong`,children:[{type:`text`,value:`reviewable`}]},{type:`text`,value:`: the same task + dataset + metrics produce comparable runs every time, and every run becomes a durable, shareable record.`}]},{type:`heading`,level:2,text:`How it works`,children:[{type:`text`,value:`How it works`}],id:`how-it-works`},{type:`paragraph`,variant:`body`,children:[{type:`text`,value:`Every run follows the same pipeline, no matter how you score:`}]},{type:`code-block`,code:`dataset item  →  task()  →  output  →  metric(s)  →  EvaluationResult
                                                       ├─ artifacts (CSV / JSON / XLSX)
                                                       └─ optional live stream to the platform`,label:`pipeline`,highlightLanguage:null,softWrap:!1},{type:`list`,ordered:!1,items:[{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`Dataset item`}]},{type:`text`,value:` — an input (and usually an expected output) to evaluate against.`}]},{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`Task`}]},{type:`text`,value:` — your function: it receives the input and returns your system's output.`}]},{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`Metrics`}]},{type:`text`,value:` — score the output (deterministic checks, custom code, or an LLM judge).`}]},{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`Result`}]},{type:`text`,value:` — aggregate scores plus per-item detail, saved as artifacts and optionally streamed here for review.`}]}]},{type:`heading`,level:2,text:`SDK vs. platform`,children:[{type:`text`,value:`SDK vs. platform`}],id:`sdk-vs-platform`},{type:`paragraph`,variant:`body`,children:[{type:`text`,value:`There are two pieces, and you can use the first without the second:`}]},{type:`list`,ordered:!1,items:[{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`The SDK`}]},{type:`text`,value:` (`},{type:`inline-code`,value:`pip install qym`},{type:`text`,value:`) is the implementation surface — where you write tasks, choose metrics, and run evaluations. It works fully offline.`}]},{type:`list-item`,children:[{type:`strong`,children:[{type:`text`,value:`The platform`}]},{type:`text`,value:` (this app) stores runs, shows trends, and supports human review and approval. The SDK streams to it when you give it an API key.`}]}]},{type:`callout`,tone:`tip`,children:[{type:`callout-title`,children:[{type:`text`,value:`New here?`}]},{type:`text`,value:` Go straight to `},{type:`link`,target:{kind:`internal`,pageKey:`get-started/first-run`},children:[{type:`text`,value:`Your first run`}]},{type:`text`,value:` — you can get a green run in under a minute with zero credentials.`}]}]};export{e as default};